package kindergarten

import (
	"errors"
	"sort"
	"strings"
)

// Garden represents a kindergarten garden.
type Garden struct {
	rows   [2]string
	students map[string][]string
}

var plantNames = map[byte]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

func NewGarden(diagram string, children []string) (*Garden, error) {
	if !strings.HasPrefix(diagram, "\n") {
		return nil, errors.New("diagram must start with a newline")
	}
	rows := strings.Split(diagram, "\n")
	if len(rows) != 3 || len(rows[1]) != len(rows[2]) || len(rows[1])%2 != 0 {
		return nil, errors.New("diagram must have two rows of equal, even length")
	}
	for _, r := range rows[1:3] {
		for i := 0; i < len(r); i++ {
			if _, ok := plantNames[r[i]]; !ok {
				return nil, errors.New("invalid cup code")
			}
		}
	}

	// Sort a copy of the children; the argument must not be modified.
	sorted := make([]string, len(children))
	copy(sorted, children)
	sort.Strings(sorted)

	seen := make(map[string]bool, len(sorted))
	for _, c := range sorted {
		if seen[c] {
			return nil, errors.New("duplicate child name")
		}
		seen[c] = true
	}

	g := &Garden{
		rows:     [2]string{rows[1], rows[2]},
		students: make(map[string][]string, len(sorted)),
	}
	for i, c := range sorted {
		off := 2 * i
		g.students[c] = []string{
			plantNames[rows[1][off]],
			plantNames[rows[1][off+1]],
			plantNames[rows[2][off]],
			plantNames[rows[2][off+1]],
		}
	}
	return g, nil
}

func (g *Garden) Plants(child string) ([]string, bool) {
	plants, ok := g.students[child]
	return plants, ok
}
```

